    rows = [r for r in range(h) if sum(x != frame for x in grid[r]) <= 2]
    cols = [c for c in range(w) if sum(grid[r][c] != frame for r in range(h)) <= 2]

    # Interior/background color is the most common non-frame color.
    counts = {x: n for x, n in freq.items() if x != frame}
    background = max(counts, key=counts.get)

    out = []
    for ri in range(len(rows) - 1):
        line = []
        for ci in range(len(cols) - 1):
